CREATE TABLE IF NOT EXISTS "qa_clients" (
  "id" uuid PRIMARY KEY NOT NULL,
  "owner_id" uuid NOT NULL,
  "client_name" text NOT NULL,
  "status" text NOT NULL DEFAULT 'active'
);

